package vn.svframe.svframelib.api.crafting.recipes.vmp; import vn.svframe.svframelib.api.crafting.recipes.SVFrameRecipeStation; import java.util.*; public class ModernSmithingStationMapping extends VanillaInventoryMapping { public int getMainWidth(int r){return 1;} public int getMainHeight(int c){return 1;} public int getMainSlot(int x,int y){if(x!=0||y!=0)throw outOfBounds(x,y);return 1;} public int getMainInventoryStart(){return 1;} public int getMainInventoryWidth(){return 1;} public int getMainInventoryHeight(){return 1;} public int getResultWidth(int r){return 1;} public int getResultHeight(int c){return 1;} public int getResultSlot(int x,int y){if(x!=0||y!=0)throw outOfBounds(x,y);return 3;} public int getResultInventoryStart(){return 3;} public int getResultInventoryWidth(){return 1;} public int getResultInventoryHeight(){return 1;} public boolean isResultSlot(int s){return s==3;} public int getSideWidth(String n,int r){validateSide(n);return 1;} public int getSideHeight(String n,int c){validateSide(n);return 1;} public int getSideSlot(String n,int x,int y){validateSide(n);if(x!=0||y!=0)throw outOfBounds(x,y);return "template".equals(n)?0:2;} public int getSideInventoryStart(String n){return getSideSlot(n,0,0);} public int getSideInventoryWidth(String n){validateSide(n);return 1;} public int getSideInventoryHeight(String n){validateSide(n);return 1;} public boolean mainIsResult(){return false;} public ArrayList<String> getSideInventoryNames(){return new ArrayList<>(List.of("template","ingot"));} public String getIntendedInventory(){return "SMITHING";} public SVFrameRecipeStation getIntendedStation(){return SVFrameRecipeStation.SMITHING;} }
